        STYLES.put("KINGDRAGON:3", 115); // king_dragon_king_stan -> skin_kingStan
        STYLES.put("KINGDRAGON:5", 117); // king_dragon_queen_scarlet -> skin_queenScarlet
        STYLES.put("KINGDRAGON:6", 116); // king_dragon_queen_celeste -> skin_queenCeleste
        STYLES.put("KINGDRAGON:210", 100); // birthday_mistik -> mio_king_dragon_bday_mistik
        STYLES.put("KINGDRAGON:212", 114); // king_dragon_king_nightbringer -> mio_king_dragon_community25_kingnightbringer
        STYLES.put("LANDMONSTER:211", 118); // lava_monster_classic -> mio_lava_monster_classic
